export const assets={"/icons/favicon-32.png": {"type": "image/png", "base64": true, "body": ""}, "/favicon.ico": {"type": "image/x-icon", "base64": true, "body": ""}, "/icons/icon-192.png": {"type": "image/png", "base64": true, "body": ""}, "/icons/badge.png": {"type": "image/png", "base64": true, "body": ""}, "/icons/apple-touch-icon.png": {"type": "image/png", "base64": true, "body": ""}, "/icons/icon-512.png": {"type": "image/png", "base64": true, "body": ""}, "/sw.js": {"type": "application/javascript", "body": "const STATIC='luxtips-static-v1';\nself.addEventListener('install',event=>event.waitUntil(caches.open(STATIC).then(c=>c.addAll(['/offline.html','/icons/icon-192.png','/icons/icon-512.png'])).then(()=>self.skipWaiting())));\nself.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('luxtips-static-')&&k!==STATIC).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));\nself.addEventListener('fetch',event=>{\n const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;\n // Forecasts and API responses are always network-only. No old betting data offline.\n if(event.request.mode==='navigate')event.respondWith(fetch(event.request).catch(()=>caches.match('/offline.html')));\n else if(u.pathname.startsWith('/icons/'))event.respondWith(caches.match(event.request).then(r=>r||fetch(event.request)));\n});\nself.addEventListener('push',event=>event.waitUntil((async()=>{\n let p;try{p=event.data.json();}catch{return;}\n const u=new URL(p.url,self.location.origin);if(u.origin!==self.location.origin)return;\n const db=await caches.open('luxtips-push-seen-v1'),key=new Request(self.location.origin+'/__push_seen/'+encodeURIComponent(p.id));\n if(await db.match(key))return;\n await self.registration.showNotification(p.title||'LuxTips',{body:p.body,icon:'/icons/icon-192.png',badge:'/icons/badge.png',tag:'luxtips-'+p.id,renotify:false,data:{url:u.href}});\n await db.put(key,new Response(String(Date.now())));\n const keys=await db.keys();if(keys.length>256)await Promise.all(keys.slice(0,keys.length-256).map(k=>db.delete(k)));\n})()));\nself.addEventListener('notificationclick',event=>{\n event.notification.close();event.waitUntil((async()=>{\n const url=new URL(event.notification.data?.url||'/',self.location.origin);if(url.origin!==self.location.origin)return;\n const clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});\n for(const c of clients)if(new URL(c.url).origin===url.origin){await c.navigate(url.href);return c.focus();}\n return self.clients.openWindow(url.href);\n })());\n});\n"}, "/pwa-client.js": {"type": "application/javascript", "body": "(async()=>{\n const panel=document.querySelector('#pwa-panel'),status=document.querySelector('#pwa-status'),enable=document.querySelector('#pwa-enable'),disable=document.querySelector('#pwa-disable'),install=document.querySelector('#pwa-install'),football=document.querySelector('#pwa-football'),nba=document.querySelector('#pwa-nba');\n const say=s=>status.textContent=s;let prompt,registration,config,subscription;\n let standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;\n const updateControls=()=>{\n  const active=!!subscription;\n  install.hidden=!!standalone||active;\n  document.querySelector('#pwa-install-help').hidden=!!standalone||active;\n  panel.dataset.active=String(active);\n  panel.querySelector('summary').title=active?'Notificações ativas':'Notificações';\n };\n updateControls();\n document.addEventListener('click',event=>{if(!panel.contains(event.target))panel.open=false;});\n panel.addEventListener('keydown',event=>{if(event.key==='Escape'){panel.open=false;panel.querySelector('summary').focus();}});\n window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();prompt=event;updateControls();});\n install.onclick=async()=>{if(prompt){await prompt.prompt();await prompt.userChoice;prompt=null;}else say('No iPhone: Partilhar → Adicionar ao ecrã principal. Noutros dispositivos, usa a opção Instalar aplicação do navegador.');};\n window.addEventListener('appinstalled',()=>{standalone=true;updateControls();say('LuxTips instalado.');});\n if(!('serviceWorker' in navigator)){say('Este navegador não permite instalar o LuxTips.');enable.disabled=true;return;}\n try{\n  registration=await navigator.serviceWorker.register('/sw.js',{scope:'/'});await navigator.serviceWorker.ready;\n  config=await fetch('/api/push/config',{cache:'no-store'}).then(r=>r.json());\n  if(!('PushManager' in window)||!('Notification' in window)){say('Para receber notificações no iPhone, adiciona primeiro o LuxTips ao ecrã principal.');enable.disabled=true;return;}\n  subscription=await registration.pushManager.getSubscription();\n  const saved=JSON.parse(localStorage.getItem('luxtips-push')||'null');\n  if(saved){football.checked=saved.football;nba.checked=false;}\n  updateControls();disable.hidden=!subscription;enable.textContent=subscription?'Guardar preferências':'Ativar notificações';\n  if(!config.enabled){say('As notificações estão temporariamente indisponíveis.');enable.disabled=true;}\n }catch{say('Não foi possível preparar as notificações. Tenta atualizar a página.');enable.disabled=true;}\n const token=()=>{let value=localStorage.getItem('luxtips-push-token');if(!value){value=Array.from(crypto.getRandomValues(new Uint8Array(32)),n=>n.toString(16).padStart(2,'0')).join('');localStorage.setItem('luxtips-push-token',value);}return value;};\n const bytes=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));\n enable.onclick=async()=>{\n  if(!football.checked){say('Escolhe Futebol.');return;}\n  enable.disabled=true;\n  try{\n   const permission=await Notification.requestPermission();\n   if(permission!=='granted'){say('Notificações não autorizadas. Podes alterar a permissão nas definições do navegador.');return;}\n   subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes(config.publicKey)});\n   const prefs={football:football.checked,nba:false};\n   const r=await fetch('/api/push/subscription',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token()},body:JSON.stringify({subscription:subscription.toJSON(),preferences:prefs})});\n   if(!r.ok)throw Error();localStorage.setItem('luxtips-push',JSON.stringify(prefs));\n   updateControls();say('Notificações ativas para novas entradas. Atualizações de odds e reentradas não repetem o aviso.');disable.hidden=false;enable.textContent='Guardar preferências';\n  }catch{say('Não foi possível ativar. Tenta novamente.');}finally{enable.disabled=false;}\n };\n disable.onclick=async()=>{\n  disable.disabled=true;\n  try{\n   subscription=await registration.pushManager.getSubscription();\n   if(subscription){const r=await fetch('/api/push/subscription',{method:'DELETE',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token()},body:JSON.stringify({endpoint:subscription.endpoint})});if(!r.ok)throw Error();await subscription.unsubscribe();}\n   localStorage.removeItem('luxtips-push');subscription=null;updateControls();disable.hidden=true;enable.textContent='Ativar notificações';say('Notificações desativadas neste dispositivo.');\n  }catch{say('Não foi possível desativar. Tenta novamente.');}finally{disable.disabled=false;}\n };\n const jump=new URL(location.href).searchParams.get('jogo');\n if(jump){const observer=new MutationObserver(()=>{const el=document.querySelector('[data-fixture=\"'+CSS.escape(jump)+'\"]');if(el){el.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});observer.disconnect();}});observer.observe(document.body,{childList:true,subtree:true});setTimeout(()=>observer.disconnect(),20000);}\n})();\n"}, "/offline.html": {"type": "text/html; charset=utf-8", "body": "<!doctype html><html lang=\"pt-PT\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#101820\"><title>LuxTips — Sem ligação</title><style>body{margin:0;background:#101820;color:#f5f5f5;font:18px system-ui;display:grid;min-height:100dvh;place-items:center}main{max-width:28rem;padding:2rem}img{width:80px;border-radius:18px}a{color:#ceff75}p{line-height:1.5}</style><main><img src=\"/icons/icon-192.png\" alt=\"LuxTips\"><h1>Sem ligação</h1><p>Os prognósticos precisam de uma ligação à Internet para mostrar dados atuais.</p><a href=\"/\">Tentar novamente</a></main></html>\n"}};

